    # Winner/loser log-prob sums (per example)
    log_prob_w = batch.get("log_prob_w", None)
    if log_prob_w is None:
        log_prob_w = extra["log_prob_w"]

    log_prob_l = batch.get("log_prob_l", None)
    if log_prob_l is None:
        log_prob_l = extra["log_prob_l"]

    # Objective signal: prefer delta_z, else cost gap (cost_b - cost_a).
    obj = batch.get("delta_z", None)
    if obj is None:
        obj = extra.get("delta_z", None)

    if obj is None:
        cost_a = batch.get("cost_a", None)
        if cost_a is None:
            cost_a = extra.get("cost_a", None)
        cost_b = batch.get("cost_b", None)
        if cost_b is None:
            cost_b = extra.get("cost_b", None)
        if (cost_a is not None) and (cost_b is not None):
            obj = cost_b - cost_a

    base_weight = batch.get("weight", None)
    if base_weight is None:
        base_weight = extra.get("weight", None)

    hp = extra.get("hyperparams", {})
    alpha = float(extra.get("alpha", hp.get("alpha", 1.0)))
    scale = float(extra.get("scale", hp.get("scale", 1.0)))
    m_max = float(extra.get("m_max", hp.get("m_max", 5.0)))
    eps = float(extra.get("eps", hp.get("eps", 1e-6)))

    d = log_prob_w - log_prob_l

    if obj is None:
        obj = ops.zeros_like(d)

    # Z-score for affine invariance; clamp to keep logits in a stable range.
    m = scale * ops.zscore(obj, eps=eps)
    m = ops.clamp(m, -m_max, m_max)

    logits = alpha * d + m
    per_pair = ops.softplus(-logits)

    if base_weight is not None:
        per_pair = per_pair * base_weight

    return per_pair.mean()

